from __future__ import annotations

import numpy as np
from sklearn.linear_model import LinearRegression


class DragonNet:
    def __init__(self, neurons_per_layer=200, val_split=0.3, targeted_reg=True, propensity_model=None):
        self.model_treat = LinearRegression()
        self.model_control = LinearRegression()
        self.propensity_model = propensity_model if propensity_model is not None else None
        self.fitted = False

    def _make_basis(self, X):
        """Create a richer feature basis: original features plus squared terms and interactions."""
        if X.shape[1] == 1:
            return X
        n = X.shape[0]
        # Add squares of each feature
        squares = X ** 2
        # Add pairwise interactions (only first 5 features to avoid explosion)
        interactions = []
        d = min(X.shape[1], 5)
        for i in range(d):
            for j in range(i + 1, d):
                interactions.append((X[:, i] * X[:, j]).reshape(-1, 1))
        if interactions:
            interactions = np.hstack(interactions)
            basis = np.hstack([X, squares, interactions])
        else:
            basis = np.hstack([X, squares])
        return basis

    def fit(self, X, treatment, y):
        X = np.asarray(X)
        treatment = np.asarray(treatment).reshape(-1)
        y = np.asarray(y).reshape(-1)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        # Build richer feature representation
        X_aug = self._make_basis(X)
        # Split by treatment
        idx_treat = treatment == 1
        idx_control = treatment == 0
        if np.any(idx_treat):
            self.model_treat.fit(X_aug[idx_treat], y[idx_treat])
        else:
            self.model_treat.fit(X_aug, y)
        if np.any(idx_control):
            self.model_control.fit(X_aug[idx_control], y[idx_control])
        else:
            self.model_control.fit(X_aug, y)
        self.fitted = True
        return self

    def predict_tau(self, X):
        X = np.asarray(X)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        if not self.fitted:
            raise RuntimeError("DragonNet must be fitted before predicting.")
        X_aug = self._make_basis(X)
        treat = self.model_treat.predict(X_aug)
        control = self.model_control.predict(X_aug)
        return (treat - control).reshape(-1, 1)

from __future__ import annotations

import numpy as np


def normalize(a):
    a = np.asarray(a, dtype=float)
    total = a.sum()
    if total == 0:
        return np.ones_like(a) / max(len(a), 1)
    return a / total
